# Generated by scripts/release/chocolatey.sh from packaging/chocolatey/template.
$ErrorActionPreference = 'Stop'

$toolsDir = Split-Path -Parent $MyInvocation.MyCommand.Definition

$packageArgs = @{
  packageName    = $env:ChocolateyPackageName
  unzipLocation  = $toolsDir
  url64bit       = '@URL@'
  checksum64     = '@SHA256@'
  checksumType64 = 'sha256'
}
Install-ChocolateyZipPackage @packageArgs

# Chocolatey shims every .exe in the package as a command (`spacebadger`).
# The .gui marker makes the shim start the window without waiting for it.
$exe = Join-Path $toolsDir 'SpaceBadger-@VERSION@-windows-x64\SpaceBadger.exe'
if (-not (Test-Path $exe)) {
  throw "SpaceBadger.exe not found at $exe"
}
New-Item -ItemType File -Path "$exe.gui" -Force | Out-Null
